package main

import "math"

// Which weather provider answers a location: IPMA inside Portugal, Open-Meteo everywhere else.
//
// IPMA is used when the point is in Portugal (inPortugal) AND within maxPlaceKm of one of the 35
// IPMA forecast places. The outline is what makes the border honest: a distance rule alone cannot
// do it, because a Portuguese town can be farther from an IPMA place (Barrancos, 79 km) than a
// Spanish one (Tui, 42 km). The distance test is only a second line of defence against a wrong
// outline.
//
// The outline (pt_outline.go) is generated by tools/make_pt_outline.py from Natural Earth 1:10m data,
// which is coarse by about a kilometre: a pin within a kilometre of the Spanish border may land on
// either side (both answers are good forecasts), and a town on the water front (Viana do Castelo,
// Cascais, Figueira da Foz) can lie outside the land polygon. So the water up to coastMarginKm off
// a coast edge counts as Portugal too, while the border edges get no margin.

// coastMarginKm is how far off a coast edge of the outline a pin still counts as Portugal.
const coastMarginKm = 1.5

// outlinePoint is one vertex of an outline, in degrees. Border: the edge from this point to the
// next one runs along the border with Spain (false: along the coast).
type outlinePoint struct {
	Lat, Lon float64
	Border   bool
}

// outlineBox is a latitude/longitude rectangle (the island groups, which have no polygon of their own).
type outlineBox struct {
	Name                           string
	LatMin, LatMax, LonMin, LonMax float64
}

func (b outlineBox) contains(lat, lon float64) bool {
	return lat >= b.LatMin && lat <= b.LatMax && lon >= b.LonMin && lon <= b.LonMax
}

// inRing is the ray-casting test: a ray towards east from the point crosses the ring's edges an odd
// number of times when the point is inside. The ring is not closed (the last point joins the first).
func inRing(ring []outlinePoint, lat, lon float64) bool {
	in := false
	for i, j := 0, len(ring)-1; i < len(ring); j, i = i, i+1 {
		a, b := ring[i], ring[j]
		if (a.Lat > lat) != (b.Lat > lat) && lon < (b.Lon-a.Lon)*(lat-a.Lat)/(b.Lat-a.Lat)+a.Lon {
			in = !in
		}
	}
	return in
}

// segmentKm is the distance in kilometres from a point to the segment a-b (flat approximation around the point).
func segmentKm(lat, lon float64, a, b outlinePoint) float64 {
	const kmPerDeg = 111.195
	kx := math.Cos(lat*math.Pi/180) * kmPerDeg
	ax, ay := (a.Lon-lon)*kx, (a.Lat-lat)*kmPerDeg
	bx, by := (b.Lon-lon)*kx, (b.Lat-lat)*kmPerDeg
	dx, dy := bx-ax, by-ay
	t := 0.0
	if l2 := dx*dx + dy*dy; l2 > 0 {
		t = math.Max(0, math.Min(1, -(ax*dx+ay*dy)/l2))
	}
	return math.Hypot(ax+t*dx, ay+t*dy)
}

// nearCoast: a point outside the polygon is still Portugal when the nearest piece of the outline is a
// coast edge and no farther than coastMarginKm. A point whose nearest piece is a border edge (Tui,
// Badajoz, Ayamonte) is not.
func nearCoast(ring []outlinePoint, lat, lon float64) bool {
	coast, border := math.Inf(1), math.Inf(1)
	for i, a := range ring {
		d := segmentKm(lat, lon, a, ring[(i+1)%len(ring)])
		if a.Border {
			border = math.Min(border, d)
		} else {
			coast = math.Min(coast, d)
		}
	}
	return coast <= coastMarginKm && coast < border
}

// inPortugal reports whether the point is on the mainland (the polygon, or the water just off its
// coast) or in the Madeira or Azores box.
func inPortugal(lat, lon float64) bool {
	for _, b := range ptIslandBoxes {
		if b.contains(lat, lon) {
			return true
		}
	}
	return inRing(ptMainland, lat, lon) || nearCoast(ptMainland, lat, lon)
}

// ipmaCovers is the choosing rule: in Portugal and within maxPlaceKm of an IPMA place.
func (w *Weather) ipmaCovers(lat, lon float64) bool {
	if !inPortugal(lat, lon) {
		return false
	}
	_, d := w.nearestPlace(lat, lon)
	return d <= w.maxPlaceKm
}
